    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import deque, Counter
def comps_of(I):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c] and not seen[r][c]:
                col=I[r][c]; q=[(r,c)]; seen[r][c]=True; cells=[]
                while q:
                    x,y=q.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            n=(x+dx,y+dy)
                            if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and I[n[0]][n[1]]==col:
                                seen[n[0]][n[1]]=True; q.append(n)
                out.append((col,cells))
    return out

def invs(cells):
    return {'h':set(map(lambda tc:tc[0],cells)),
            'm':set(c-r for r,c in cells),
            'a':set(r+c for r,c in cells)}

