def solve(I, p=5, family=None, slotfn=None):
    if family is None: family='m'
    if slotfn is None: slotfn=lambda cells,minv: minv
    C=comps_of(I); H,W=len(I),len(I[0])
    cnt=Counter()
    mm={}
    for col,cells in C:
        v=set(invs(cells)[family])
