def classify_and_slot(cells):
    # horizontal bar (single row): family h, slot = min row
    rs=[r for r,c in cells]
    cs=[c for r,c in cells]
    if max(rs)-min(rs)==0: return ('h', min(rs))
    dd={c-r for r,c in cells}; ss={r+c for r,c in cells}
    if len(dd)==1: return ('m', next(iter(dd)))
    if len(ss)==1: return ('a', next(iter(ss)))
    return None

def build(P, p, final):
    res=[]
    if 'h' in P: res=[[final[r%p] for c in range(len(I))] for r in range(len(I))]
    elif 'm' in P: res=[[final[(c-r)%p] for c in range(len(I[0]))] for r in range(len(I))]
    else: res=[[final[(r+c)%p] for c in range(len(I[0]))] for r in range(len(I))]
    return res

