    f=final[:]
    for i,v in enumerate(f):
        if v is None:
            lo=i-1
            while lo>=0 and f[lo] is None: lo-=1
            hi=i+1
            while hi<p and f[hi] is None: hi+=1
            f[i]=f[lo] if lo>=0 else (f[hi] if hi<p else f[(i-1-p)%p])
    return f

