import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
from collections import deque, Counter
def comps_of(I):
    H,W=len(I),len(I[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if I[r][c] and not seen[r][c]:
                col=I[r][c]; q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            n=(x+dx,y+dy)
                            if 0<=n[0]<H and 0<=n[1]<W and not seen[n[0]][n[1]] and I[n[0]][n[1]]==col:
                                seen[n[0]][n[1]]=True; q.append(n)
                out.append((col,cells))
    return out

def classify(cells):
    rs=[r for r,c in cells]
    dd={c-r for r,c in cells}; ss={r+c for r,c in cells}
    spreads=[('h',max(rs)-min(rs)),('m',len(dd)-1),('a',len(ss)-1)]
    best=min(spreads,key=lambda sp:sp[1])
    fam,spread=best
    vals={'h':rs,'m':dd,'a':ss}[fam]
    return fam, sorted(vals)

def nearest_fill(final, p):
    f=final[:]
    for i,v in enumerate(f):
        if v is None:
            lo=i-1
            while lo>=0 and f[lo] is None: lo-=1
            hi=i+1
            while hi<p and f[hi] is None: hi+=1
            f[i]=f[lo] if lo>=0 else (f[hi] if hi<p else None)
    return f

def solve(I):
    C=comps_of(I); H,W=len(I),len(I[0])
    info=[]
    for col,cells in C:
        fam,vals=classify(cells)
        info.append({'col':col,'fam':fam,'slots':vals})
    # find smallest p where every slot maps uniquely (multiple slots of same color ok if distinct keys)
    for pp in range(2,30):
        mm={}
        ok=True
        for e in info:
            for s in e['slots']:
                k=s%pp
                if k in mm and mm[k]!=e['col']: ok=False;break
                mm[k]=e['col']
            if not ok: break
        if ok: p=pp;break
    p=p
    mm={}
    for e in info:
        for s in e['slots']:
            mm[s%p]=mm.get(s%p,e['col'])
    P=[mm.get(i,None) for i in range(p)]
    final=nearest_fill(P,p)
    maj=max(set(e['fam'] for e in info),key=lambda f:sum(1 for e in info if e['fam']==f))
    res=[]
    if maj=='h': res=[[final[r%p] for c in range(W)] for r in range(H)]
    elif maj=='m': res=[[final[(c-r)%p] for c in range(W)] for r in range(H)]
    else: res=[[final[(r+c)%p] for c in range(W)] for r in range(H)]
    return res

for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    R=solve(G[k+' input']); print(k,'match:',R==G[k+' output'])
T=solve(G['Test input'])
print(json.dumps(T))
